sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.newSection = "";
    c.addSection = function() {
        if (!c.newSection) return;
        c.server.get({
            action: "add_section",
            section_name: c.newSection,
            section_order: (c.data.sections.length + 1) * 10
        }).then(function(r) {
            c.data.sections = r.data.sections;
            c.newSection = "";
        });
    };
};

sp_widget.script:
(function() {
    data.sections = [];
    data.templateId = $sp.getParameter("template_id") || "";
    data.msg = "";
    try {
        if (!data.templateId) return;
        if (input && input.action === "add_section") {
            // First create or find the section record
            var sGr = new GlideRecord("x_1433041_identi_0_section");
            sGr.initialize();
            sGr.setValue("section_key", (input.section_name || "new_section").toLowerCase().replace(/[^a-z0-9]+/g, "_"));
            sGr.setValue("name", input.section_name || "New Section");
            if (input.description) sGr.setValue("description", input.description);
            sGr.setValue("active", true);
            var sectionId = sGr.insert();
            // Then create the template_section junction record
            if (sectionId) {
                var tsGr = new GlideRecord("x_1433041_identi_0_template_section");
                tsGr.initialize();
                tsGr.setValue("template", data.templateId);
                tsGr.setValue("section", sectionId);
                tsGr.setValue("order", input.section_order || 100);
                tsGr.setValue("active", true);
                tsGr.insert();
                data.msg = "Section added successfully.";
            }
            return;
        }
        if (input && input.action === "remove_section") {
            // Deactivate the junction record
            var rmGr = new GlideRecord("x_1433041_identi_0_template_section");
            if (input.ts_sys_id && rmGr.get(input.ts_sys_id)) {
                rmGr.setValue("active", false);
                rmGr.update();
                data.msg = "Section removed.";
            }
            return;
        }
        if (input && input.action === "reorder") {
            if (input.orders && Array.isArray(input.orders)) {
                for (var i = 0; i < input.orders.length; i++) {
                    var oGr = new GlideRecord("x_1433041_identi_0_template_section");
                    if (oGr.get(input.orders[i].ts_sys_id)) {
                        oGr.setValue("order", input.orders[i].order);
                        oGr.update();
                    }
                }
                data.msg = "Sections reordered.";
            }
            return;
        }
        // Load sections for this template via junction table
        var gr = new GlideRecord("x_1433041_identi_0_template_section");
        gr.addQuery("template", data.templateId);
        gr.addQuery("active", true);
        gr.orderBy("order");
        gr.setLimit(50);
        gr.query();
        while (gr.next()) {
            var secGr = new GlideRecord("x_1433041_identi_0_section");
            if (secGr.get(gr.getValue("section"))) {
                // Count questions in this section
                var qCount = new GlideAggregate("x_1433041_identi_0_question");
                qCount.addQuery("section", secGr.getValue("sys_id"));
                qCount.addQuery("active", true);
                qCount.addAggregate("COUNT");
                qCount.query();
                var questionCount = 0;
                if (qCount.next()) questionCount = parseInt(qCount.getAggregate("COUNT"), 10);
                data.sections.push({
                    sys_id: secGr.getValue("sys_id"),
                    ts_sys_id: gr.getValue("sys_id"),
                    name: secGr.getValue("name"),
                    section_key: secGr.getValue("section_key"),
                    description: secGr.getValue("description") || "",
                    order: gr.getValue("order"),
                    question_count: questionCount
                });
            }
        }
    } catch (e) {
        gs.error("IBAR Section Builder widget error: " + e.message);
    }
})();
